#!/usr/bin/env python3
"""Recalculo de FUN-01 P1/P4 em leitura; modelo ficticio sem biblioteca de propriedades."""
from pathlib import Path
from hashlib import sha256
from fractions import Fraction as F
import json,math,subprocess
root=Path('.'); refs={'modulos/e1-termodinamica.html':'f19000a7ddb1f3552b9633b0efec266fb3f6c5e5065808505a2f65b2005aefbc','auditoria/termodinamica/evidencias/QA-09/inventario-r13.json':'0df99b79bcc2350581fcdded72435d30d07858de237a549e6228ca73682f8d9b','assets/termodinamica/fun01-dados-v1.json':'a73b4d6140219cbd6b005216bb7a44db0a68b05f21ca51b7ac4b1ca782dd1448','assets/termodinamica/fun01-calculos-v1.mjs':'a0fbdc4e6e7291a563db2362d26f4107ad67f56843e741d96eef8eea5a8d2a88'}
for p,d in refs.items():assert sha256((root/p).read_bytes()).hexdigest()==d,p
utf=(root/'modulos/e1-termodinamica.html').read_text().encode('utf-16-le');blocks=[(111432,113604,'f2ad9153af7074ac31be0b322be23bf21a8450b3b98411b54961266c89ff94cc'),(115777,119960,'07b62072f8f3bbf46abf33e1997c4b2695faad50bdeced42bfdc34cec24fd6f2'),(131293,156859,'0fedd2cbca9364a9c1da8f6caa2e2d90d8729dcb9a120c636cad56dc2d54d206')]
for a,b,s in blocks:assert sha256(utf[2*a:2*b].decode('utf-16-le').encode()).hexdigest()==s
j=json.loads((root/'assets/termodinamica/fun01-dados-v1.json').read_text());p1=j['problema_saturacao']; sat=next(x for x in j['agua_saturacao'] if x['p_MPa']==p1['p_MPa']);frac=lambda v:F(str(v));v=frac(p1['V_m3'])/frac(p1['m_kg']);vf=frac(sat['vf_m3kg']);vg=frac(sat['vg_m3kg']);hliq=frac(sat['hf_kJkg']);hvap=frac(sat['hg_kJkg']);quality=(v-vf)/(vg-vf);h=hliq+quality*(hvap-hliq);vapor=frac(p1['m_kg'])*quality;gap=frac(p1['h_sensor_kJkg'])-frac(p1['limite_erro_sensor_kJkg'])-(h+frac(p1['tolerancia_editorial_hprev_kJkg']));assert 0<quality<1 and gap>0
col=j['equilibrio']['coluna'];T=frac(col['T_K']);rho=frac(col['rho_kgm3']);M=frac(col['M_kgmol']);grav=frac(col['g_ms2']);height=frac(col['H_m']);pbottom=frac(col['psat_Pa'])+rho*grav*height;dmu=M/rho*(pbottom-frac(col['psat_Pa']));assert pbottom==29620 and dmu==F('0.3924')==M*grav*height
D=j['equilibrio']['celulas']; R=frac(D['R_JmolK']);t=frac(D['T_K']);V=frac(D['V_m3']);p0=frac(D['p0_Pa']);n0=p0*V/(R*t);ai=frac(D['yA_alpha'])*n0;bi=frac(D['yA_beta'])*n0;af=(ai+bi)/2;bf=af;Balpha=n0-ai;Bbeta=n0-bi;pa=(af+Balpha)*R*t/V;pb=(bf+Bbeta)*R*t/V;yA=af/(af+Balpha);yB=bf/(bf+Bbeta);ntrans=ai-af;curv=R*t*(1/af+1/bf);dmuA=float(R*t)*math.log(4)
assert pa==70000 and pb==130000 and yA==F(5,7) and yB==F(5,13) and ntrans>0 and curv>0;assert af+bf==ai+bi and Balpha+Bbeta==n0
node='import {calcularFun01} from "./assets/termodinamica/fun01-calculos-v1.mjs";import fs from "node:fs";let d=JSON.parse(fs.readFileSync("./assets/termodinamica/fun01-dados-v1.json"));let r=calcularFun01(d);console.log(JSON.stringify({s:r.saturacao,e:r.equilibrio,n:r.testes.length}))'
res=json.loads(subprocess.check_output(['node','--input-type=module','-e',node],text=True));r=res['s'];e=res['e'];close=lambda a,b:math.isclose(float(a),float(b),rel_tol=1e-10,abs_tol=1e-9)
for k,val in [('v_m3kg',v),('x',quality),('m_vapor_kg',vapor),('h_previsto_kJkg',h),('separacao_minima_kJkg',gap)]:assert close(r[k],val),k
for k,val in [('pressao_fundo_Pa',pbottom),('delta_mu_intrinseco_Jmol',dmu),('delta_muA_inicial_Jmol',dmuA),('transferencia_A_mol',ntrans),('p_alpha_Pa',pa),('p_beta_Pa',pb),('yA_alpha',yA),('yA_beta',yB),('curvatura_F_Jmol2',curv)]:assert close(e[k],val),k
print(json.dumps({'ok':True,'P1':{'v_m3kg':float(v),'titulo':float(quality),'massa_vapor_kg':float(vapor),'h_previsto_kJkg':float(h),'separacao_minima_kJkg':float(gap)},'P4':{'pressao_fundo_Pa':float(pbottom),'delta_mu_intrinseco_Jmol':float(dmu),'n0_mol':float(n0),'delta_mu_A_Jmol':dmuA,'transferencia_A_mol':float(ntrans),'p_alpha_Pa':float(pa),'p_beta_Pa':float(pb),'yA_alpha':float(yA),'yA_beta':float(yB),'d2F_dxi2_Jmol2':float(curv)},'testes_internos_FUN01':res['n'],'limite':'Confronto analitico localizado; nao e auditoria independente deste lote.'},ensure_ascii=False,indent=2))
